#include <stdio.h>

struct rec {
    int fish;
    int bonus;
};

void give_bonus(struct rec *r, int k) {
    r->bonus = r->bonus + k;
}

int main(void) {
    struct rec list[8] = {0};
    int n = 0;
    if (scanf("%d", &n) != 1) {
        return 1;
    }

    for (int i = 0; i < n; i++) {
        if (scanf("%d", &list[i].fish) != 1) {
            return 1;
        }
    }

    int top = 0;
    for (int i = 1; i < n; i++) {
        if (list[i].fish > list[top].fish) {
            top = i;
        }
    }

    give_bonus(&list[top], 10);

    for (int i = 0; i < n; i++) {
        printf("第 %d 号：%d 条，奖励 %d 条喵\n", i + 1, list[i].fish, list[i].bonus);
